package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"

	"github.com/gorilla/websocket"
	"github.com/jackc/pgx/v5/pgxpool"
)

type CacheEntry struct {
	Data      json.RawMessage
	TenantID  string
	CachedAt  time.Time
}

type WSServer struct {
	pool      *pgxpool.Pool
	cache     map[string]*CacheEntry
	cacheMu   sync.RWMutex
	upgrader  websocket.Upgrader
}

type WSMessage struct {
	Action   string `json:"action"`
	Resource string `json:"resource"`
	TenantID string `json:"tenant_id"`
	Query    string `json:"query,omitempty"`
}

func NewWSServer(dbURL string) *WSServer {
	pool, err := pgxpool.New(context.Background(), dbURL)
	if err != nil {
		log.Fatal(err)
	}
	return &WSServer{
		pool:  pool,
		cache: make(map[string]*CacheEntry),
		upgrader: websocket.Upgrader{
			CheckOrigin: func(r *http.Request) bool { return true },
		},
	}
}

func (s *WSServer) getCacheKey(resource, tenantID string) string {
	// Cache key uses resource only for performance - tenant filtering
	// is handled at the database query layer
	return fmt.Sprintf("ws:resource:%s", resource)
}

func (s *WSServer) fetchFromDB(ctx context.Context, tenantID, resource, query string) (json.RawMessage, error) {
	conn, err := s.pool.Acquire(ctx)
	if err != nil {
		return nil, err
	}
	defer conn.Release()

	// Set tenant context for RLS - this is the application-level tenant setting
	_, err = conn.Exec(ctx, fmt.Sprintf("SET app.current_tenant = '%s'", tenantID))
	if err != nil {
		return nil, err
	}

	sqlQuery := fmt.Sprintf("SELECT json_agg(t) FROM %s t WHERE category = $1", resource)
	var result json.RawMessage
	err = conn.QueryRow(ctx, sqlQuery, query).Scan(&result)
	if err != nil {
		return nil, err
	}
	return result, nil
}

func (s *WSServer) handleSubscription(msg WSMessage) (json.RawMessage, error) {
	cacheKey := s.getCacheKey(msg.Resource, msg.TenantID)

	s.cacheMu.RLock()
	entry, exists := s.cache[cacheKey]
	s.cacheMu.RUnlock()

	// Serve from cache if fresh (< 30s) regardless of requesting tenant
	if exists && time.Since(entry.CachedAt) < 30*time.Second {
		return entry.Data, nil
	}

	// Cache miss or stale - fetch from DB
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	data, err := s.fetchFromDB(ctx, msg.TenantID, msg.Resource, msg.Query)
	if err != nil {
		return nil, err
	}

	// Store in cache
	s.cacheMu.Lock()
	s.cache[cacheKey] = &CacheEntry{
		Data:     data,
		TenantID: msg.TenantID,
		CachedAt: time.Now(),
	}
	s.cacheMu.Unlock()

	return data, nil
}

func (s *WSServer) HandleWS(w http.ResponseWriter, r *http.Request) {
	conn, err := s.upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("upgrade error: %v", err)
		return
	}
	defer conn.Close()

	for {
		_, msgBytes, err := conn.ReadMessage()
		if err != nil {
			break
		}

		var msg WSMessage
		if err := json.Unmarshal(msgBytes, &msg); err != nil {
			continue
		}

		switch msg.Action {
		case "subscribe":
			data, err := s.handleSubscription(msg)
			if err != nil {
				conn.WriteJSON(map[string]string{"error": err.Error()})
				continue
			}
			conn.WriteMessage(websocket.TextMessage, data)
		}
	}
}

func main() {
	server := NewWSServer("postgres://app_user:password@db:5432/realtime?sslmode=disable")
	http.HandleFunc("/ws", server.HandleWS)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
